<template><div class="pm-dashboard-layout" :class="{'pm-sidebar-hidden':hidden}"><AppSidebar :isOpen="open" @close="open=false"/><div class="pm-dashboard-main"><div class="pm-dashboard-topbar"><button class="pm-icon-btn pm-menu-btn" @click="open=!open">☰</button><button class="pm-icon-btn pm-hide-btn" @click="hidden=!hidden">←</button><div class="pm-topbar-page-title">Repairs & Maintenance</div><div class="pm-topbar-search"><input class="form-control" v-model="search" placeholder="Search..."/></div><div class="pm-topbar-actions"><button class="pm-icon-btn">♧<span class="pm-topbar-dot">5</span></button><button class="pm-icon-btn">✉</button></div><div class="pm-topbar-user"><div class="pm-topbar-avatar">JD</div><span class="pm-topbar-name">John Doe</span></div></div><div class="rm"><header><div><h1>{{formMode?'New Repair & Maintenance Record':'Repairs & Maintenance'}}</h1><p>Dashboard　›　Vehicle Management　›　Repairs & Maintenance　›　{{formMode?'New Record':'List'}}</p></div><button class="btn btn-primary" @click="formMode=!formMode">{{formMode?'← Back to List':'+ Add Repair Record'}}</button></header><template v-if="!formMode"><section class="filters"><input v-model="search" placeholder="Search by Job Order No., Vehicle No., Driver, etc..."/><input type="date"/><select><option>All Job Types</option></select><select><option>All Status</option></select><select><option>All Priority</option></select><button>Reset</button><button class="btn btn-primary">Filter</button></section><section class="list"><table><thead><tr><th>#</th><th>Job Order No.</th><th>Job Date</th><th>Vehicle No.</th><th>Vehicle / Model</th><th>Driver</th><th>Job Type</th><th>Priority</th><th>Status</th><th>Total Cost ($)</th><th>Invoice No.</th><th>Actions</th></tr></thead><tbody><tr v-for="(x,i) in rows" :key="x.id"><td>{{i+1}}</td><td>{{x.job_order_no}}</td><td>{{date(x.job_date)}}</td><td>{{x.vehicle?.vehicle_number}}</td><td>{{x.vehicle?.make_brand}} {{x.vehicle?.model}}</td><td>{{x.driver?.driver_name||'—'}}</td><td>{{x.job_type}}</td><td><b :class="x.priority.toLowerCase()">{{x.priority}}</b></td><td><em>{{x.work_status}}</em></td><td>{{x.total_paid}}</td><td>{{x.invoice_no}}</td><td>◉　⋮</td></tr></tbody></table></section></template><template v-else><div class="form"><section><h2>1　Vehicle Info</h2><label>Vehicle Number<select v-model="f.vehicle_id"><option value="">Select vehicle</option><option v-for="v in vehicles" :value="v.id">{{v.vehicle_number}} — {{v.make_brand}} {{v.model}}</option></select></label><label>Current Odometer (KM)<input v-model="f.next_service_odometer" type="number"/></label></section><section><h2>2　Driver Info</h2><label>Driver<select v-model="f.driver_id"><option value="">Select driver</option><option v-for="d in drivers" :value="d.id">{{d.driver_name}}</option></select></label><label>Service Provider<input v-model="f.service_provider"/></label></section><section><h2>3　Job Order Info</h2><label>Job Date<input v-model="f.job_date" type="date"/></label><label>Job Type<select v-model="f.job_type"><option>Maintenance</option><option>Oil Change</option><option>Brake Service</option><option>Mechanical Repair</option></select></label><label>Priority<select v-model="f.priority"><option>Low</option><option>Medium</option><option>High</option></select></label><label>Work Status<select v-model="f.work_status"><option>Pending</option><option>Under Repair</option><option>Completed</option></select></label></section><section><h2>4　Financial Info</h2><label>Invoice No.<input v-model="f.invoice_no"/></label><label>Subtotal<input v-model="f.subtotal" type="number"/></label><label>Sales Tax<input v-model="f.sales_tax" type="number"/></label><label>Total Paid<input v-model="f.total_paid" type="number"/></label></section><section class="wide"><h2>5　Job Details</h2><label>Description of Work / Service Performed<textarea v-model="f.description"></textarea></label><label>Next Service Date<input v-model="f.next_service_date" type="date"/></label><label>Notes<textarea v-model="f.notes"></textarea></label></section></div><footer><button class="btn btn-success" @click="save">Save</button><button class="btn btn-outline-secondary" @click="formMode=false">Cancel</button></footer></template></div></div></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import AppSidebar from'../components/AppSidebar.vue';import client from'../api/client';const open=ref(false),hidden=ref(false),formMode=ref(false),search=ref(''),rows=ref([]),vehicles=ref([]),drivers=ref([]);const f=reactive({vehicle_id:'',driver_id:'',job_date:new Date().toISOString().slice(0,10),job_type:'Maintenance',priority:'Medium',work_status:'Pending',service_provider:'',invoice_no:'',subtotal:0,sales_tax:0,total_paid:0,description:'',next_service_date:'',next_service_odometer:'',notes:''});const date=x=>x?new Date(x).toLocaleDateString():'—';async function load(){rows.value=(await client.get('/repair-maintenance-records',{params:{per_page:50,search:search.value}})).data.data.data;vehicles.value=(await client.get('/vehicles',{params:{per_page:200}})).data.data.data;drivers.value=(await client.get('/drivers',{params:{per_page:200}})).data.data.data}async function save(){await client.post('/repair-maintenance-records',{...f,vehicle_id:+f.vehicle_id,driver_id:f.driver_id?+f.driver_id:null});formMode.value=false;load()}onMounted(load)</script>
<style scoped>.rm header{display:flex;justify-content:space-between;margin-bottom:24px}.rm h1{font-size:28px;color:#061b83;margin:0}.rm p{color:#0735c0;font-size:13px}.filters{display:grid;grid-template-columns:2fr repeat(4,1fr) .6fr .6fr;gap:14px;padding:20px;border:1px solid #e0e8f4;border-radius:8px}.filters input,.filters select{height:38px;border:1px solid #dce5f3;border-radius:4px;padding:8px}.list{margin-top:18px;overflow:auto;border:1px solid #dfe7f3}.list table{width:100%;border-collapse:collapse;font-size:12px}.list th,.list td{padding:13px;border:1px solid #e5ebf4;white-space:nowrap}.list th{color:#061a83}.list b,.list em{padding:5px 9px;border-radius:4px;font-style:normal}.high{background:#ffe0e3;color:#e11}.medium{background:#fff0db;color:#e80}.low,em{background:#e3f6e9;color:#080}.form{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.form section{border:1px solid #dfe7f4;padding:16px;border-radius:8px}.form h2{font-size:15px;color:#073df2}.form label{display:inline-block;width:48%;padding:8px;color:#061b7d;font-size:12px;font-weight:700}.form input,.form select,.form textarea{display:block;width:100%;height:36px;border:1px solid #dce5f3;border-radius:4px;margin-top:5px}.form textarea{height:70px}.form .wide{grid-column:1/-1}footer{margin-top:12px;display:flex;gap:10px}@media(max-width:900px){.filters,.form{grid-template-columns:1fr}.form label{width:100%}}</style>
